from speechbrain.inference import VAD
import torchaudio

wav_path='/root/input.wav'
vad = VAD.from_hparams(source='speechbrain/vad-crdnn-libriparty', savedir='/root/.cache/speechbrain/vad-crdnn')
boundaries = vad.get_speech_segments(wav_path)
segments=[]
if boundaries.numel()>0:
    b=boundaries.detach().cpu().numpy().tolist()
    for i in range(0,len(b),2):
        segments.append((float(b[i]), float(b[i+1])))
print('segments', len(segments))
# merge close gaps
merged=[]
for start,end in segments:
    if not merged:
        merged.append([start,end])
    else:
        if start - merged[-1][1] <= 0.5:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start,end])
print('merged', len(merged))
